interface Drawable{void draw();}abstract class Shape{abstract double calculateArea();void display(){System.out.printf("Area: %.2f%n",calculateArea());}}class Circle extends Shape implements Drawable{double r;Circle(double r){this.r=r;}double calculateArea(){return Math.PI*r*r;}public void draw(){System.out.println("Drawing Circle");}}class Rectangle extends Shape implements Drawable{double l,w;Rectangle(double l,double w){this.l=l;this.w=w;}double calculateArea(){return l*w;}public void draw(){System.out.println("Drawing Rectangle");}}public class Q3_Shape_Abstract_Class_Interface{public static void main(String[]x){Circle c=new Circle(5);Rectangle r=new Rectangle(4,6);c.draw();c.display();r.draw();r.display();}}
